/*
 * Spawns a class 0xB8 shot for `owner` at `pos` heading along `dir`, living
 * `life` frames, with two glows (bluish, or reddish for an owner of class
 * 0xFF, which also keeps full scale). Returns the new moby or 0.
 */
struct Moby *FUN_L04_002aee30(struct Moby *owner, void *pos, void *dir, int life)
{
    struct Moby *m;
    ShotVars *vars;
    OvlQuad pos_q;
    OvlQuad dir_q;
    Vec4f *p = (Vec4f *)&pos_q;
    Vec4f *d = (Vec4f *)&dir_q;

    pos_q = *(OvlQuad *)pos;
    dir_q = *(OvlQuad *)dir;
    m = create_moby(0xB8);
    if (m != 0) {
        vars = (ShotVars *)m->pvars;
        vars->owner = owner;
        m->unk30 = 0xFF;
        m->unk32 = 0xFF;
        m->unk31 = 1;
        if (owner->oclass != 0xFF)
            m->scale = m->scale * 0.5f;
        m->rot.x = 0.0f;
        m->rot.y = 0.0f;
        m->rot.z = atan2_f(d->x, d->y);
        qcopy(&m->pos, p);
        qcopy(&vars->dir, d);
        vars->spin = random_float_between(-(D_0015ED6C * 1.5707964f), D_0015ED6C * 1.5707964f);
        vars->unk14 = 0;
        vars->time = life;
        vars->time_max = life;
        vars->hero_dist = FUN_001f9b48(&m->pos, &hero.motion.pos);
        vars->unk24 = 0;
        vars->unk28 = 0;
        if (owner->oclass == 0xFF) {
            FUN_L00_0026daa0(m, 0x2F7F4F4F, life * 5 / 4, -1, 100000.0f);
            FUN_L00_0026daa0(m, 0x4F7F7F7F, life * 5 / 4, -1, 40000.0f);
        } else {
            FUN_L00_0026daa0(m, 0x2F4F7F7F, life * 5 / 4, -1, 100000.0f);
            FUN_L00_0026daa0(m, 0x4F6F7F7F, life * 5 / 4, -1, 40000.0f);
        }
        FUN_L00_00250df8(m);
    }
    return m;
}
